import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import {
    ShoppingCart, MagnifyingGlassIcon, FunnelIcon,
    EyeIcon, TruckIcon, CheckCircleIcon, XCircleIcon,
    ClockIcon, ArrowPathIcon, UsersIcon,
    ChevronDownIcon, MapPinIcon, PhoneIcon, EnvelopeIcon
} from '@heroicons/react/24/outline';
import toast from 'react-hot-toast';
import orderService from '../../services/orderService';
import StatCard from '../../components/ui/StatCard';
import SectionCard from '../../components/ui/SectionCard';
import StatusBadge from '../../components/ui/StatusBadge';
import EmptyState from '../../components/ui/EmptyState';
import Pagination from '../../components/ui/Pagination';
import Modal from '../../components/ui/Modal';
import PageHeader from '../../components/ui/PageHeader';
import { DollarSign, Package, TrendingUp, Clock } from 'lucide-react';

const statusTabs = [
    { key: '', label: 'All Orders', icon: ShoppingCart },
    { key: 'pending', label: 'Pending', icon: ClockIcon },
    { key: 'assigned', label: 'Assigned', icon: UsersIcon },
    { key: 'confirmed', label: 'Confirmed', icon: CheckCircleIcon },
    { key: 'processing', label: 'Processing', icon: ArrowPathIcon },
    { key: 'dispatched', label: 'Dispatched', icon: TruckIcon },
    { key: 'delivered', label: 'Delivered', icon: CheckCircleIcon },
    { key: 'cancelled', label: 'Cancelled', icon: XCircleIcon },
];

const OrderManagement = () => {
    const [search, setSearch] = useState('');
    const [page, setPage] = useState(1);
    const [statusFilter, setStatusFilter] = useState('');
    const [viewingOrder, setViewingOrder] = useState(null);
    const [assigningOrder, setAssigningOrder] = useState(null);
    const [selectedSalesRep, setSelectedSalesRep] = useState('');
    const queryClient = useQueryClient();

    const { data: ordersData, isLoading } = useQuery({
        queryKey: ['orders', { search, page, status: statusFilter }],
        queryFn: () => orderService.getAllOrders({ search, page, limit: 10, status: statusFilter })
    });

    const { data: salesReps } = useQuery({
        queryKey: ['sales-reps-list'],
        queryFn: () => orderService.getAllOrders().then(() => [])
    });

    const assignMutation = useMutation({
        mutationFn: () => orderService.assignOrders(),
        onSuccess: (data) => {
            toast.success(`${data.data?.length || 0} orders assigned`);
            queryClient.invalidateQueries(['orders']);
            setAssigningOrder(null);
        },
        onError: () => toast.error('Failed to assign orders')
    });

    const statusMutation = useMutation({
        mutationFn: ({ orderId, status }) => orderService.updateOrderStatus(orderId, status),
        onSuccess: () => {
            toast.success('Order status updated');
            queryClient.invalidateQueries(['orders']);
            setViewingOrder(null);
        },
        onError: (error) => toast.error(error.response?.data?.message || 'Failed to update')
    });

    const orders = ordersData?.data || [];
    const pagination = ordersData?.pagination;

    const stats = {
        total: pagination?.total || 0,
        revenue: orders.filter(o => ['delivered', 'completed'].includes(o.status)).reduce((sum, o) => sum + o.totalAmount, 0),
        pending: orders.filter(o => o.status === 'pending').length,
        completed: orders.filter(o => ['delivered', 'completed'].includes(o.status)).length,
    };

    return (
        <div className="space-y-6">
            <PageHeader
                icon={ShoppingCart}
                title="Order Management"
                description="View and manage all customer orders"
                actions={
                    <button
                        onClick={() => assignMutation.mutate()}
                        disabled={assignMutation.isLoading}
                        className="flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-brand-700 to-brand-900 text-white rounded-xl hover:from-brand-800 hover:to-brand-950 transition-all font-semibold shadow-lg shadow-brand-500/25 text-sm disabled:opacity-50"
                    >
                        <UsersIcon className="w-5 h-5" />
                        {assignMutation.isLoading ? 'Assigning...' : 'Auto-Assign Orders'}
                    </button>
                }
            />

            {/* Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Total Orders" value={stats.total} icon={ShoppingCart} color="navy" loading={isLoading} />
                <StatCard label="Revenue" value={`$${stats.revenue.toLocaleString()}`} icon={DollarSign} color="emerald" loading={isLoading} />
                <StatCard label="Pending" value={stats.pending} icon={Clock} color="gold" loading={isLoading} />
                <StatCard label="Completed" value={stats.completed} icon={CheckCircleIcon} color="teal" loading={isLoading} />
            </div>

            {/* Status Tabs */}
            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                {statusTabs.map((tab) => (
                    <button
                        key={tab.key}
                        onClick={() => { setStatusFilter(tab.key); setPage(1); }}
                        className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${statusFilter === tab.key
                                ? 'bg-brand-700 text-white shadow-lg shadow-brand-500/25'
                                : 'bg-white dark:bg-brand-900 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-brand-700 hover:bg-slate-50 dark:hover:bg-brand-800'
                            }`}
                    >
                        <tab.icon className="w-4 h-4" />
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* Orders Table */}
            <SectionCard title="Orders" subtitle={`${pagination?.total || 0} orders found`}>
                {isLoading ? (
                    <div className="space-y-3">
                        {[...Array(6)].map((_, i) => (
                            <div key={i} className="animate-pulse flex items-center gap-4 py-4">
                                <div className="h-12 w-12 bg-slate-200 dark:bg-brand-700 rounded-xl" />
                                <div className="flex-1 space-y-2">
                                    <div className="h-4 w-40 bg-slate-200 dark:bg-brand-700 rounded" />
                                    <div className="h-3 w-24 bg-slate-200 dark:bg-brand-700 rounded" />
                                </div>
                                <div className="h-6 w-20 bg-slate-200 dark:bg-brand-700 rounded-full" />
                            </div>
                        ))}
                    </div>
                ) : orders.length === 0 ? (
                    <EmptyState
                        icon={ShoppingCart}
                        title="No orders found"
                        description={statusFilter ? `No ${statusFilter} orders. Try a different filter.` : 'Orders will appear here when customers place them.'}
                        searchTerm={search || statusFilter}
                        hasFilters={!!statusFilter}
                        onClear={() => { setStatusFilter(''); setSearch(''); }}
                    />
                ) : (
                    <>
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-slate-100 dark:divide-brand-700">
                                <thead>
                                    <tr className="bg-slate-50/50 dark:bg-brand-800/30">
                                        <th className="px-4 py-4 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Order ID</th>
                                        <th className="px-4 py-4 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Product</th>
                                        <th className="px-4 py-4 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Customer</th>
                                        <th className="px-4 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">Amount</th>
                                        <th className="px-4 py-4 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">Status</th>
                                        <th className="px-4 py-4 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">Payment</th>
                                        <th className="px-4 py-4 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">Date</th>
                                        <th className="px-4 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 dark:divide-brand-700">
                                    {orders.map((order, idx) => (
                                        <motion.tr
                                            key={order.id}
                                            initial={{ opacity: 0 }}
                                            animate={{ opacity: 1 }}
                                            transition={{ delay: idx * 0.02 }}
                                            className="hover:bg-brand-50/30 dark:hover:bg-brand-800/20 transition-colors group cursor-pointer"
                                            onClick={() => setViewingOrder(order)}
                                        >
                                            <td className="px-4 py-4 text-sm font-mono text-slate-500">#{order.id?.slice(0, 8)}</td>
                                            <td className="px-4 py-4 text-sm font-semibold text-brand-800 dark:text-white">{order.productName}</td>
                                            <td className="px-4 py-4 text-sm text-slate-600 dark:text-slate-400">{order.customer?.firstName} {order.customer?.lastName}</td>
                                            <td className="px-4 py-4 text-sm font-bold text-right">${order.totalAmount?.toFixed(2)}</td>
                                            <td className="px-4 py-4 text-center"><StatusBadge status={order.status} size="sm" /></td>
                                            <td className="px-4 py-4 text-center">
                                                <span className={`text-xs font-semibold px-2 py-1 rounded-full ${order.isPaid ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700'}`}>
                                                    {order.isPaid ? 'Paid' : 'Unpaid'}
                                                </span>
                                            </td>
                                            <td className="px-4 py-4 text-xs text-slate-500 text-center">
                                                {new Date(order.createdAt).toLocaleDateString()}
                                            </td>
                                            <td className="px-4 py-4 text-right">
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); setViewingOrder(order); }}
                                                    className="p-2 text-slate-400 hover:text-brand-600 transition-colors rounded-lg hover:bg-slate-100 dark:hover:bg-brand-800 opacity-0 group-hover:opacity-100"
                                                >
                                                    <EyeIcon className="w-4 h-4" />
                                                </button>
                                            </td>
                                        </motion.tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <Pagination pagination={pagination} onPageChange={setPage} />
                    </>
                )}
            </SectionCard>

            {/* Order Detail Modal */}
            <Modal
                isOpen={!!viewingOrder}
                onClose={() => setViewingOrder(null)}
                title={`Order #${viewingOrder?.id?.slice(0, 8)}`}
                subtitle="Order details and management"
                size="lg"
                footer={
                    viewingOrder && (
                        <>
                            {viewingOrder.status === 'pending' && (
                                <button
                                    onClick={() => statusMutation.mutate({ orderId: viewingOrder.id, status: 'cancelled' })}
                                    className="px-5 py-2.5 border-2 border-rose-300 text-rose-700 rounded-xl hover:bg-rose-50 transition font-medium text-sm"
                                >
                                    Cancel Order
                                </button>
                            )}
                            {['assigned', 'confirmed', 'processing', 'dispatched'].includes(viewingOrder.status) && (
                                <button
                                    onClick={() => statusMutation.mutate({ orderId: viewingOrder.id, status: 'cancelled' })}
                                    className="px-5 py-2.5 border-2 border-rose-300 text-rose-700 rounded-xl hover:bg-rose-50 transition font-medium text-sm"
                                >
                                    Cancel Order
                                </button>
                            )}
                            <button onClick={() => setViewingOrder(null)} className="px-5 py-2.5 border-2 border-slate-300 dark:border-brand-600 rounded-xl hover:bg-white dark:hover:bg-brand-800 transition font-medium text-sm">
                                Close
                            </button>
                        </>
                    )
                }
            >
                {viewingOrder && (
                    <div className="space-y-6">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="bg-slate-50 dark:bg-brand-800/50 rounded-xl p-4">
                                <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Status</p>
                                <StatusBadge status={viewingOrder.status} />
                            </div>
                            <div className="bg-slate-50 dark:bg-brand-800/50 rounded-xl p-4">
                                <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Payment</p>
                                <p className="font-bold text-brand-800 dark:text-white">{viewingOrder.paymentMethod} {viewingOrder.isPaid ? '• Paid' : '• Unpaid'}</p>
                            </div>
                        </div>

                        <div>
                            <h4 className="text-sm font-semibold text-brand-800 dark:text-white mb-3 flex items-center gap-2">
                                <Package className="w-4 h-4" /> Product Details
                            </h4>
                            <div className="bg-slate-50 dark:bg-brand-800/50 rounded-xl p-4">
                                <p className="font-semibold text-brand-800 dark:text-white">{viewingOrder.productName}</p>
                                <p className="text-sm text-slate-500">Quantity: {viewingOrder.quantity}</p>
                                <p className="text-lg font-bold text-brand-800 dark:text-white mt-2">${viewingOrder.totalAmount?.toFixed(2)}</p>
                            </div>
                        </div>

                        {viewingOrder.customer && (
                            <div>
                                <h4 className="text-sm font-semibold text-brand-800 dark:text-white mb-3 flex items-center gap-2">
                                    <UsersIcon className="w-4 h-4" /> Customer Information
                                </h4>
                                <div className="bg-slate-50 dark:bg-brand-800/50 rounded-xl p-4 space-y-2">
                                    <div className="flex items-center gap-2 text-sm">
                                        <span className="font-semibold">{viewingOrder.customer.firstName} {viewingOrder.customer.lastName}</span>
                                    </div>
                                    <div className="flex items-center gap-2 text-sm text-slate-500">
                                        <EnvelopeIcon className="w-4 h-4" /> {viewingOrder.customer.email}
                                    </div>
                                    <div className="flex items-center gap-2 text-sm text-slate-500">
                                        <PhoneIcon className="w-4 h-4" /> {viewingOrder.customer.phone}
                                    </div>
                                    <div className="flex items-center gap-2 text-sm text-slate-500">
                                        <MapPinIcon className="w-4 h-4" /> {viewingOrder.customer.address}, {viewingOrder.customer.city}, {viewingOrder.customer.state}
                                    </div>
                                </div>
                            </div>
                        )}

                        {viewingOrder.salesRep && (
                            <div>
                                <h4 className="text-sm font-semibold text-brand-800 dark:text-white mb-3 flex items-center gap-2">
                                    <UsersIcon className="w-4 h-4" /> Assigned Sales Rep
                                </h4>
                                <div className="bg-brand-50 dark:bg-brand-800/30 rounded-xl p-4">
                                    <p className="font-semibold text-brand-800 dark:text-white">{viewingOrder.salesRep.firstName} {viewingOrder.salesRep.lastName}</p>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </Modal>
        </div>
    );
};

export default OrderManagement;
